-- Тема 02: уточнения по проверке Codex (31 исправлений в 12 вопросах), ключи не меняются.
-- Источник: scripts/questions/070_codex_topic02_fixes.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'К какой базе подключится psql, если имя базы не указано ни в команде, ни в переменных окружения?', NULL, NULL, NULL, 'К какой базе подключится psql, если база не задана ни аргументами, ни переменными окружения, ни сервисом? Режим -l не используется.'),
        ('question', 'Какая команда psql показывает параметры текущего подключения?', NULL, NULL, NULL, 'Какая метакоманда psql показывает сводку о текущем подключении — база, роль, узел или сокет и порт, — не создавая нового соединения?'),
        ('question', 'Что делает ON_ERROR_ROLLBACK = on?', NULL, NULL, NULL, 'Что делает ON_ERROR_ROLLBACK = on при ошибке SQL-команды в открытой транзакции?'),
        ('question', 'psql запущен без ключа -U, переменная окружения PGUSER не задана. От имени какой роли он подключится?', NULL, NULL, NULL, 'От имени какой роли подключится psql, если роль не задана ни одним способом: ни ключом -U, ни аргументом, ни строкой подключения, ни переменными окружения, ни сервисом?'),
        ('question', 'Переменная PGHOST не задана. Чем подключение psql -h localhost отличается от подключения без ключа -h на том же компьютере с Linux?', NULL, NULL, NULL, 'В Linux сравнивают psql -h localhost и запуск без -h. PGHOST и PGHOSTADDR не заданы, строка подключения и сервис не используются. Чем отличаются способы подключения?'),
        ('option', 'К какой базе подключится psql, если база не задана ни аргументами, ни переменными окружения, ни сервисом? Режим -l не используется.', 'К базе postgres, созданной вместе с кластером', NULL, 'Выбирается по умолчанию, только если так зовут пользователя или это задано явно, например переменной PGDATABASE.', 'При условиях вопроса база postgres выбирается, только если роль называется postgres; наличие этой базы само по себе не делает её значением по умолчанию.'),
        ('option', 'Какая метакоманда psql показывает сводку о текущем подключении — база, роль, узел или сокет и порт, — не создавая нового соединения?', '\connect', NULL, '\connect (сокращённо \c) открывает новое подключение.', 'Открывает новое соединение; без аргументов повторно использует прежние параметры.'),
        ('option', 'Какая метакоманда psql показывает сводку о текущем подключении — база, роль, узел или сокет и порт, — не создавая нового соединения?', '\dconfig', NULL, 'Показывает параметры сервера, а не подключения.', 'Показывает текущие значения параметров конфигурации сервера, включая настройки сеанса; это не сводка реквизитов подключения.'),
        ('option', 'Какая метакоманда psql показывает сводку о текущем подключении — база, роль, узел или сокет и порт, — не создавая нового соединения?', '\encoding', NULL, 'Показывает кодировку клиента, а не параметры подключения.', 'Без аргумента показывает текущую клиентскую кодировку; сводку с базой, ролью, узлом и портом выводит \conninfo.'),
        ('option', 'Что означает восклицательный знак в приглашении psql, например `student=!#`?', 'Транзакция прервана ошибкой и ждёт отката', NULL, 'Команды игнорируются до конца транзакции: нужен ROLLBACK или откат к точке сохранения.', 'После ошибки обычные SQL-команды отклоняются. Можно завершить транзакцию откатом либо выполнить ROLLBACK TO к ранее созданной точке сохранения и продолжить работу. COMMIT в таком состоянии тоже завершает транзакцию откатом.'),
        ('option', 'Что делает ON_ERROR_ROLLBACK = on при ошибке SQL-команды в открытой транзакции?', 'Перед каждой командой ставит точку сохранения', 'Откатывает команду к неявной точке сохранения', 'Точка сохранения ставится перед каждой командой внутри транзакции, и при ошибке откатывается только эта команда; транзакцию можно продолжить.', 'Внутри транзакции psql создаёт неявную точку сохранения перед SQL-командой. Если команда завершается ошибкой, выполняется откат к этой точке, и работу в транзакции можно продолжить.'),
        ('option', 'Что делает команда psql \! pwd?', 'Выполняет команду ОС pwd', 'Выполняет команду операционной системы pwd', '\! запускает команду оболочки ОС.', NULL),
        ('option', 'Что показывает команда psql 16 \dconfig без шаблона имени параметра, в отличие от \dconfig *?', 'Параметры со значениями, отличными от встроенных по умолчанию', 'Параметры, чьи значения отличаются от встроенных', 'Без шаблона команда отбирает параметры с источником не default и значением, отличным от boot_val.', 'Без шаблона команда отбирает параметры с источником не default и значением, отличным от встроенного значения по умолчанию (boot_val).'),
        ('option', 'От имени какой роли подключится psql, если роль не задана ни одним способом: ни ключом -U, ни аргументом, ни строкой подключения, ни переменными окружения, ни сервисом?', 'Роли postgres, главного суперпользователя кластера', 'Роли postgres, независимо от пользователя ОС', 'postgres — обычное имя суперпользователя, но psql подставит его, только если так зовут пользователя ОС.', NULL),
        ('option', 'От имени какой роли подключится psql, если роль не задана ни одним способом: ни ключом -U, ни аргументом, ни строкой подключения, ни переменными окружения, ни сервисом?', 'Роли с именем пользователя ОС, запустившего psql', NULL, 'Если такой роли в кластере нет, подключение завершится ошибкой «роль не существует».', 'Используется имя пользователя ОС. Подключение возможно, если такая роль существует и имеет нужные права; иначе будет ошибка «роль не существует».'),
        ('option', 'В Linux сравнивают psql -h localhost и запуск без -h. PGHOST и PGHOSTADDR не заданы, строка подключения и сервис не используются. Чем отличаются способы подключения?', 'Без -h psql подключается по TCP к адресу 127.0.0.1', NULL, 'Без -h и PGHOST psql в Linux выбирает Unix-сокет в каталоге по умолчанию.', 'При условиях вопроса psql без -h в Linux выбирает Unix-сокет в каталоге по умолчанию.'),
        ('option', 'В Linux сравнивают psql -h localhost и запуск без -h. PGHOST и PGHOSTADDR не заданы, строка подключения и сервис не используются. Чем отличаются способы подключения?', 'С -h localhost — по TCP, без -h — через Unix-сокет', NULL, 'С -h localhost подключение идёт по TCP через петлевой интерфейс, без -h — через Unix-сокет. Это видно в выводе \conninfo: «через сокет в …» или «компьютер localhost, адрес …».', 'При условиях вопроса с -h localhost подключение идёт по TCP через петлевой интерфейс, без -h — через Unix-сокет. Это видно в выводе \conninfo: «через сокет в …» или «компьютер localhost, адрес …».'),
        ('option', 'Что верно о справке в psql?', 'psql --help — ключи запуска psql из командной строки', 'psql --help — справка по ключам запуска', 'Ту же справку внутри psql выводит \? options.', NULL),
        ('option', 'Что верно о справке в psql?', '\? variables — специальные переменные psql', '\? variables — справка по переменным psql', 'Например, AUTOCOMMIT, ON_ERROR_ROLLBACK, PROMPT1.', NULL),
        ('option', 'Что верно о справке в psql?', '\? — синтаксис команд SQL, например SELECT', '\? — справка по синтаксису команд SQL', 'Синтаксис команд SQL показывает \h.', NULL),
        ('option', 'Что верно о справке в psql?', '\h — справка по метакомандам psql, например \d', '\h — справка по метакомандам psql', '\h показывает синтаксис команд SQL, например \h SELECT.', NULL),
        ('option', 'Что верно о справке в psql?', '\? — список метакоманд psql', '\? — справка по метакомандам psql', 'Метакоманды начинаются с обратной косой черты и выполняются самим psql, а не сервером.', NULL),
        ('option', 'Что можно понять по стандартному приглашению psql?', 'Знак > в конце означает, что транзакция прервана ошибкой', 'Знак > в конце — транзакция прервана ошибкой', 'Прерванную транзакцию обозначает восклицательный знак: student=!>.', NULL),
        ('option', 'Что можно понять по стандартному приглашению psql?', 'Звёздочка после знака равенства означает подключение по сети', 'Звёздочка после = — подключение по сети', 'Способ подключения в стандартном приглашении не виден; его показывает \conninfo.', NULL),
        ('option', 'Что можно понять по стандартному приглашению psql?', 'Звёздочка после знака равенства — открыт блок транзакции', 'Звёздочка после = — открыт блок транзакции', 'Например, student=*>. После COMMIT или ROLLBACK звёздочка пропадает.', NULL),
        ('option', 'Что можно понять по стандартному приглашению psql?', 'Минус вместо знака равенства — запрос продолжается на следующей строке', 'Минус вместо = — ввод запроса продолжается', 'Например, student->. Приглашение для второй и следующих строк задаёт переменная PROMPT2.', NULL),
        ('option', 'В psql переменная v содержит строку «старое». Затем выполнен запрос SELECT g AS v FROM generate_series(1, 3) g \gset. Что произойдёт?', 'Будут созданы переменные v1, v2 и v3 по числу строк', 'psql сообщит об ошибке и удалит переменную v', '\gset не нумерует строки: имена переменных берутся из имён столбцов.', 'Если результат содержит несколько строк, \gset оставляет прежнее значение v.'),
        ('option', 'В psql переменная v содержит строку «старое». Затем выполнен запрос SELECT g AS v FROM generate_series(1, 3) g \gset. Что произойдёт?', 'psql сообщит об ошибке, а v сохранит значение «старое»', 'psql сообщит об ошибке и сохранит v без изменений', '\gset требует ровно одну строку результата: при нескольких строках psql сообщает, что запрос вернул больше одной строки, и ничего не записывает.', NULL),
        ('option', 'В psql переменная v содержит строку «старое». Затем выполнен запрос SELECT g AS v FROM generate_series(1, 3) g \gset. Что произойдёт?', 'В v запишется 3 — значение из последней строки', 'psql завершит запрос успешно и запишет в v число 3', 'При нескольких строках psql ничего не записывает и сообщает об ошибке.', NULL),
        ('option', 'В psql переменная v содержит строку «старое». Затем выполнен запрос SELECT g AS v FROM generate_series(1, 3) g \gset. Что произойдёт?', 'В v запишется 1 — значение из первой строки', 'psql завершит запрос успешно и запишет в v число 1', 'При нескольких строках psql ничего не записывает и сообщает об ошибке.', NULL),
        ('option', 'Что подставляет спецификатор %I в функции format?', 'Значение как имя объекта, в кавычках при надобности', 'Значение как экранированный SQL-идентификатор', 'format(''SELECT count(*) FROM %I'', ''my table'') даст SELECT count(*) FROM "my table".', '%I форматирует один SQL-идентификатор: при необходимости заключает его в двойные кавычки и экранирует внутренние двойные кавычки. Например, format(''SELECT count(*) FROM %I'', ''my table'') даст SELECT count(*) FROM "my table".')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
